+  const actionMatch = rule.action === "*" || rule.action === request.action;
+  const resourceMatch = resourceMatches(rule.resource, request.resource);
+  return roleMatch && actionMatch && resourceMatch;
+}
+
+function resourceMatches(pattern: string, resource: string): boolean {
+  if (pattern === resource || pattern === "*") return true;
+  if (pattern.endsWith("/*")) {
+    return resource.startsWith(pattern.slice(0, -1));
+  }
+  return false;
 }

 /** Decide a request against an ordered rule list. */
 export function isAllowed(rules: Rule[], request: AccessRequest): boolean {
-  throw new Error("not implemented");
